<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class PageView extends Model {public $timestamps=false; protected $fillable=['visitor_hash','session_id','user_id','path','route_name','method','ip_address','user_agent','referer','response_ms','created_at']; protected $casts=['created_at'=>'datetime']; public function user(){return $this->belongsTo(User::class);} }
